"use client"

import * as React from "react"
import { cn } from "cn"
import { ChevronRightIcon, PlusIcon } from "lucide-react"

import { Badge } from "@tecton/react/components/badge"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@tecton/react/components/collapsible"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupAction,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarMenuSub,
  SidebarMenuSubButton,
  SidebarMenuSubItem,
  SidebarTrigger,
} from "@tecton/react/components/sidebar"

import { project as defaultProject } from "../data"
import type { Project } from "../data"

type ProjectSidebarProps = React.ComponentProps<typeof Sidebar> & {
  project?: Project
  selectedAlternative?: string | null
  onSelectAlternative?: (id: string) => void
}

/** Decision-gate track: passed gates filled, the current one outlined, upcoming ones muted. */
function GateTrack({
  gates,
  className,
}: {
  gates: Project["gates"]
  className?: string
}) {
  return (
    <div
      data-slot="gate-track"
      className={cn("flex flex-col gap-1.5", className)}
    >
      <div className="flex items-center px-1" aria-hidden>
        {gates.map((gate, index) => (
          <React.Fragment key={gate.id}>
            <span
              className={cn(
                "size-2.5 shrink-0 rotate-45 border",
                gate.state === "passed" && "border-primary bg-primary",
                gate.state === "current" && "border-primary bg-background",
                gate.state === "upcoming" &&
                  "border-border-strong bg-background"
              )}
            />
            {index < gates.length - 1 ? (
              <span
                className={cn(
                  "h-px flex-1",
                  gate.state === "passed" ? "bg-primary" : "bg-border"
                )}
              />
            ) : null}
          </React.Fragment>
        ))}
      </div>
      <ol
        className="flex justify-between text-[10px] text-muted-foreground"
        aria-label="Decision gates"
      >
        {gates.map((gate) => (
          <li
            key={gate.id}
            aria-current={gate.state === "current" ? "step" : undefined}
            className={cn(
              "w-6 text-center first:text-start last:text-end",
              gate.state === "current" && "text-foreground"
            )}
          >
            {gate.id}
          </li>
        ))}
      </ol>
    </div>
  )
}

/**
 * Left panel of the project detail page: status, asset, decision-gate
 * track and the list of concepts with their field development
 * alternatives.
 */
function ProjectSidebar({
  className,
  project = defaultProject,
  selectedAlternative,
  onSelectAlternative,
  ...props
}: ProjectSidebarProps) {
  return (
    <Sidebar
      data-slot="project-sidebar"
      collapsible="offcanvas"
      className={cn("border-e border-border-subtle", className)}
      {...props}
    >
      <SidebarHeader className="flex-row items-center justify-between px-3 py-2">
        <span className="text-sm font-medium">Project details</span>
        <SidebarTrigger className="-me-1" />
      </SidebarHeader>
      <SidebarContent>
        <SidebarGroup>
          <dl className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-2 px-2 text-xs">
            <dt className="text-muted-foreground">Status</dt>
            <dd className="text-end">
              <Badge variant="outline" size="default">
                {project.status}
              </Badge>
            </dd>
            <dt className="text-muted-foreground">Asset</dt>
            <dd className="text-end font-mono">{project.asset}</dd>
            <dt className="text-muted-foreground">Concepts</dt>
            <dd className="text-end font-mono">{project.concepts.length}</dd>
          </dl>
          <GateTrack gates={project.gates} className="mt-4 px-2" />
        </SidebarGroup>
        <SidebarGroup>
          <SidebarGroupLabel>Field development alternatives</SidebarGroupLabel>
          <SidebarGroupAction aria-label="Add concept">
            <PlusIcon />
          </SidebarGroupAction>
          <SidebarMenu>
            {project.concepts.map((concept) => (
              <Collapsible
                key={concept.id}
                defaultOpen={concept.index === 1}
                className="group/collapsible"
                render={<SidebarMenuItem />}
              >
                <CollapsibleTrigger
                  render={<SidebarMenuButton tooltip={concept.name} />}
                >
                  <span className="flex size-4 shrink-0 items-center justify-center rounded-[3px] bg-muted font-mono text-[10px] text-muted-foreground">
                    {concept.index}
                  </span>
                  <span className="truncate">{concept.name}</span>
                  <span className="ms-auto font-mono text-[10px] text-muted-foreground">
                    {concept.alternatives.length} FDAs
                  </span>
                  <ChevronRightIcon className="transition-transform duration-200 group-data-open/collapsible:rotate-90" />
                </CollapsibleTrigger>
                <CollapsibleContent>
                  <SidebarMenuSub>
                    {concept.alternatives.map((alternative) => (
                      <SidebarMenuSubItem key={alternative.id}>
                        <SidebarMenuSubButton
                          render={<button type="button" />}
                          isActive={selectedAlternative === alternative.id}
                          onClick={() => onSelectAlternative?.(alternative.id)}
                        >
                          <span className="truncate">{alternative.name}</span>
                          <span className="ms-auto font-mono text-[10px] text-muted-foreground">
                            {alternative.id}
                          </span>
                        </SidebarMenuSubButton>
                      </SidebarMenuSubItem>
                    ))}
                  </SidebarMenuSub>
                </CollapsibleContent>
              </Collapsible>
            ))}
          </SidebarMenu>
        </SidebarGroup>
      </SidebarContent>
    </Sidebar>
  )
}

export { ProjectSidebar, GateTrack }
export type { ProjectSidebarProps }

"use client"

import * as React from "react"
import { ListIcon, WaypointsIcon } from "lucide-react"

import {
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
} from "@tecton/react/components/dropdown-menu"
import {
  SidebarInset,
  SidebarProvider,
  SidebarTrigger,
} from "@tecton/react/components/sidebar"
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@tecton/react/components/tabs"
import {
  ToggleGroup,
  ToggleGroupItem,
} from "@tecton/react/components/toggle-group"
import {
  PageHeader,
  PageHeaderActions,
  PageHeaderContent,
  PageHeaderNav,
  PageHeaderTitle,
} from "@tecton/react/tecton/page-header"
import { OverflowItem, OverflowSpacer } from "@tecton/react/tecton/overflow"

import { ConceptSection } from "./components/concept-section"
import { ProjectSidebar } from "./components/project-sidebar"
import { project, sectionTabs } from "./data"

type View = "list" | "graph"

/**
 * Detail page with section tabs: a project details sidebar on the left,
 * a page header carrying the section tabs and a list / graph view toggle,
 * and a scrolling body with a panel per section: concept sections on the
 * overview, a placeholder on the others.
 */
export default function Page() {
  const [section, setSection] = React.useState("overview")
  const [view, setView] = React.useState<View>("list")
  const [selected, setSelected] = React.useState<string | null>("1.01")

  return (
    <SidebarProvider>
      <ProjectSidebar
        selectedAlternative={selected}
        onSelectAlternative={setSelected}
      />
      <SidebarInset className="min-w-0">
        {/* Tabs wraps the header, which holds the tab list, and the body, which holds a panel per section. */}
        <Tabs
          value={section}
          onValueChange={(value) => setSection(String(value))}
          className="mx-auto w-full max-w-7xl gap-6 px-4 py-4 md:px-6"
        >
          <PageHeader className="items-center">
            <PageHeaderContent className="flex-none flex-row items-center gap-2">
              <SidebarTrigger className="-ms-1 md:hidden" />
              <PageHeaderTitle className="text-xl">
                {project.name}
              </PageHeaderTitle>
            </PageHeaderContent>
            <PageHeaderActions>
              {/* The tabs are one item: they collapse together into a section list in the More menu. */}
              <OverflowItem
                value="sections"
                priority={2}
                overflow={
                  <DropdownMenuRadioGroup
                    value={section}
                    onValueChange={(value) => setSection(String(value))}
                  >
                    <DropdownMenuLabel>Section</DropdownMenuLabel>
                    {sectionTabs.map((tab) => (
                      <DropdownMenuRadioItem
                        key={tab.id}
                        value={tab.id}
                        closeOnClick
                      >
                        {tab.label}
                      </DropdownMenuRadioItem>
                    ))}
                  </DropdownMenuRadioGroup>
                }
              >
                <PageHeaderNav aria-label="Project sections">
                  <TabsList aria-label="Sections" className="h-9 p-1">
                    {sectionTabs.map((tab) => (
                      <TabsTrigger key={tab.id} value={tab.id}>
                        {tab.label}
                      </TabsTrigger>
                    ))}
                  </TabsList>
                </PageHeaderNav>
              </OverflowItem>
              <OverflowSpacer />
              <OverflowItem
                value="view"
                priority={1}
                overflow={
                  <DropdownMenuRadioGroup
                    value={view}
                    onValueChange={(value) => setView(value as View)}
                  >
                    <DropdownMenuLabel>View</DropdownMenuLabel>
                    <DropdownMenuRadioItem value="list" closeOnClick>
                      <ListIcon />
                      List
                    </DropdownMenuRadioItem>
                    <DropdownMenuRadioItem value="graph" closeOnClick>
                      <WaypointsIcon />
                      Graph
                    </DropdownMenuRadioItem>
                  </DropdownMenuRadioGroup>
                }
              >
                <ToggleGroup
                  aria-label="View"
                  value={[view]}
                  onValueChange={(value) => {
                    // Pressing the pressed item keeps it: one view is always on.
                    const [next] = value
                    if (next) setView(next as View)
                  }}
                  variant="outline"
                  size="sm"
                  spacing={0}
                >
                  <ToggleGroupItem value="list" aria-label="List view">
                    <ListIcon /> List
                  </ToggleGroupItem>
                  <ToggleGroupItem value="graph" aria-label="Graph view">
                    <WaypointsIcon /> Graph
                  </ToggleGroupItem>
                </ToggleGroup>
              </OverflowItem>
            </PageHeaderActions>
          </PageHeader>

          <TabsContent value="overview">
            {view === "list" ? (
              <div className="flex flex-col gap-10">
                {project.concepts.map((concept) => (
                  <ConceptSection
                    key={concept.id}
                    concept={concept}
                    selectedAlternative={selected}
                  />
                ))}
              </div>
            ) : (
              <div className="flex min-h-96 flex-1 items-center justify-center rounded-lg border border-dashed text-sm text-muted-foreground">
                Graph view renders the concept tree here.
              </div>
            )}
          </TabsContent>
          {sectionTabs
            .filter((tab) => tab.id !== "overview")
            .map((tab) => (
              <TabsContent key={tab.id} value={tab.id}>
                <div className="flex min-h-96 items-center justify-center rounded-lg border border-dashed text-muted-foreground">
                  {tab.label} for {project.name} goes here.
                </div>
              </TabsContent>
            ))}
        </Tabs>
      </SidebarInset>
    </SidebarProvider>
  )
}

export { ProjectSidebar, GateTrack } from "./components/project-sidebar"
export {
  ConceptSection,
  AlternativeRow,
  DecisionCard,
} from "./components/concept-section"
export { project, sectionTabs, decisionCounts } from "./data"
export type {
  Project,
  Concept,
  Alternative,
  Decision,
  DecisionStatus,
} from "./data"
